<?php declare(strict_types=1);

namespace Skim\Cli\Commands;

use Skim\Cli\Command;

/**
 * CLI command that removes FrankenPHP worker mode files generated by worker:install.
 *
 * Removes:
 * - public/worker.php
 * - Caddyfile
 * - docker/Dockerfile.frankenphp
 *
 * Example:
 *   php skim worker:uninstall
 *
 * #AI:class
 */
class WorkerUninstallCommand extends \Skim\Cli\Command {
    /**
     * Removes generated worker files. #AI:handle
     */
    public function handle(): int {
        $root = SKIM_ROOT;
        $files = [
            $root . '/public/worker.php',
            $root . '/Caddyfile',
            $root . '/docker/Dockerfile.frankenphp',
        ];

        foreach ($files as $file) {
            if (is_file($file)) {
                unlink($file);
            }
        }

        $this->success('FrankenPHP worker files removed.');
        return 0;
    }
}

